/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 * }
 */
// 雙指標走 A+B 與 B+A，兩者走的總長度相同，必定在交點（或 null）相遇
// 時間複雜度: O(m + n)，空間複雜度: O(1)
function getIntersectionNode(headA, headB) {
    let a = headA, b = headB;
    while (a !== b) {
        a = a ? a.next : headB;
        b = b ? b.next : headA;
    }
    return a;
}

